import{_ as l,a0 as r,w as a,s as p,I as m,x as t,a1 as o,A as i,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"使用 smem 可视化显示Linux内存使用情况 | LCTT x X-CMD","titleTemplate":false,"description":"使用 smem 可视化显示Linux内存使用情况 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 smem 可视化显示Linux内存使用情况 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 smem 可视化显示Linux内存使用情况 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141120 How to visualize memory usage on Linux","title":"使用 smem 可视化显示Linux内存使用情况","tag":"201412","desc":""},"relativePath":"201412/20141120 How to visualize memory usage on Linux.md","filePath":"[post].md"}'),u={name:"201412/20141120 How to visualize memory usage on Linux.md"};function d(S,e,f,x,g,L){const s=r("Link");return a(),p("div",null,[e[21]||(e[21]=m("h1",{id:"使用-smem-可视化显示linux内存使用情况",tabindex:"-1"},[t("使用 smem 可视化显示Linux内存使用情况 "),m("a",{class:"header-anchor",href:"#使用-smem-可视化显示linux内存使用情况","aria-label":"Permalink to “使用 smem 可视化显示Linux内存使用情况”"},"​")],-1)),e[22]||(e[22]=m("p",null,"物理内存不足对Linux桌面系统和服务器系统的性能影响都很大。当你的计算机变慢时，要做的第一件事就是释放内存。尤其是在多用户环境以及执行关键任务的服务器环境下，内存消耗会变得更加关键，因为多个用户和应用线程会同时竞争更多的内存空间。",-1)),m("p",null,[e[1]||(e[1]=t("如果要监测系统内各种资源的使用情况（比如说CPU或内存），图形化显示是一种高效的方法，通过图形界面可以快速分析各用户和进程的资源消耗情况。本教程将给大家介绍",-1)),e[2]||(e[2]=m("strong",null,"在linux下图形化分析内存使用情况",-1)),e[3]||(e[3]=t("的方法，使用到命令行工具是",-1)),o(s,{href:"http://www.selenic.com/smem/"},{default:i(()=>[...e[0]||(e[0]=[t("smem",-1)])]),_:1}),e[4]||(e[4]=t(".",-1))]),e[23]||(e[23]=n(`<h3 id="物理内存使用情况-rss-、-pss-和-uss" tabindex="-1">物理内存使用情况: RSS 、 PSS 和 USS <a class="header-anchor" href="#物理内存使用情况-rss-、-pss-和-uss" aria-label="Permalink to “物理内存使用情况: RSS 、 PSS 和 USS”">​</a></h3><p>由于Linux使用到了虚拟内存（virtual memory），因此要准确的计算一个进程实际使用的物理内存就不是那么简单。 只知道进程的虚拟内存大小也并没有太大的用处，因为还是无法获取到实际分配的物理内存大小。</p><ul><li><strong>RSS（Resident set size）</strong>，使用top命令可以查询到，是最常用的内存指标，表示进程占用的物理内存大小。但是，将各进程的RSS值相加，通常会超出整个系统的内存消耗，这是因为RSS中包含了各进程间共享的内存。</li><li><strong>PSS（Proportional set size）</strong>会更准确一些，它将共享内存的大小进行平均后，再分摊到各进程上去。</li><li><strong>USS(Unique set size )</strong>是PSS中自己的部分，它只计算了进程独自占用的内存大小，不包含任何共享的部分。</li></ul><h3 id="安装smem" tabindex="-1">安装Smem <a class="header-anchor" href="#安装smem" aria-label="Permalink to “安装Smem”">​</a></h3><p>smem是一个能够生成多种内存耗用报告的命令行工具，它从/proc文件系统中提取各进程的PSS/USS信息，并进行汇总输出。它还内建了图表的生成能力，所以能够方便地分析整个系统的内存使用情况。</p><h4 id="在debian-ubuntu-或-linux-mint-上安装smem" tabindex="-1">在Debian, Ubuntu 或 Linux Mint 上安装smem <a class="header-anchor" href="#在debian-ubuntu-或-linux-mint-上安装smem" aria-label="Permalink to “在Debian, Ubuntu 或 Linux Mint 上安装smem”">​</a></h4><pre><code>$ sudo apt-get install smem 
</code></pre><h4 id="在fedora-或-centos-rhel上安装smem" tabindex="-1">在Fedora 或 CentOS/RHEL上安装Smem <a class="header-anchor" href="#在fedora-或-centos-rhel上安装smem" aria-label="Permalink to “在Fedora 或 CentOS/RHEL上安装Smem”">​</a></h4>`,8)),m("p",null,[e[6]||(e[6]=t("在CentOS/RHEL上，你首先得",-1)),o(s,{href:"http://xmodulo.com/how-to-set-up-epel-repository-on-centos.html"},{default:i(()=>[...e[5]||(e[5]=[t("启用",-1)])]),_:1}),e[7]||(e[7]=t("EPEL仓库。",-1))]),e[24]||(e[24]=n(`<pre><code>$ sudo yum install smem python-matplotlib 
</code></pre><h3 id="使用smem检查内存使用情况" tabindex="-1">使用smem检查内存使用情况 <a class="header-anchor" href="#使用smem检查内存使用情况" aria-label="Permalink to “使用smem检查内存使用情况”">​</a></h3><p>你可以在非特权模式下使用smem，它能够显示当前用户运行的所有进程的内存使用情况，并按照PSS的大小进行排序。</p><pre><code>$ smem 
</code></pre><p><img src="https://farm8.staticflickr.com/7498/15801819892_d017280595_z.jpg" alt=""></p><p>如有你想得到整个系统中所有用户的内存使用情况，就需要使用root权限来运行smem。</p><pre><code>$ sudo smem 
</code></pre><p><img src="https://farm9.staticflickr.com/8635/15776587626_1de74c4bcd_z.jpg" alt=""></p><p>也可以按用户维度来输出报告：</p><pre><code>$ sudo smem -u 
</code></pre><p><img src="https://farm9.staticflickr.com/8543/15798375491_510698d98f_z.jpg" alt=""></p><p>smem提供了以下选项来对输出结果进行筛选，支持按映射方式（mapping）、进程和用户三个维度的筛选：</p><ul><li>-M &lt;正则表达式&gt;</li><li>-P &lt;正则表达式&gt;</li><li>-U &lt;正则表达式&gt;</li></ul><p>想了解smem更多的使用方式，可以查询用户手册（man page）。</p><h3 id="使用smem图形化显示内存使用情况" tabindex="-1">使用smem图形化显示内存使用情况 <a class="header-anchor" href="#使用smem图形化显示内存使用情况" aria-label="Permalink to “使用smem图形化显示内存使用情况”">​</a></h3><p>图形化的报告使用起来会更加方便快捷。smem支持两种格式的图形显示方式：直方图和饼图。</p><p>下面是一些图形化显示的实例。</p><p>下面的命令行会基于PSS/RSS值，生成直方图，以用户alice为例。</p><pre><code>$ sudo smem --bar name -c &quot;pss uss&quot; -U alice 
</code></pre><p><img src="https://farm6.staticflickr.com/5616/15614838448_640e850cd8_z.jpg" alt=""></p><p>这个例子会生成一张饼图，图中显示了系统中各进程的PSS内存使用量：</p><pre><code>$ sudo smem --pie name -c &quot;pss&quot; 
</code></pre><p><img src="https://farm8.staticflickr.com/7466/15614838428_eed7426cfe_z.jpg" alt=""></p><p>概括来说，smem是一个方便易用的内存分析工具。利用smem的格式化输出，你可以对内存使用报告进行自动化分析，并执行一些自动化的处理措施。如果你还知道其他的一些优秀的内存检测工具，请在留言区告诉我。</p><hr>`,25)),m("p",null,[e[9]||(e[9]=t("via: ",-1)),o(s,{href:"http://xmodulo.com/visualize-memory-usage-linux.html"},{default:i(()=>[...e[8]||(e[8]=[t("http://xmodulo.com/visualize-memory-usage-linux.html",-1)])]),_:1})]),m("p",null,[e[13]||(e[13]=t("作者：",-1)),o(s,{href:"http://xmodulo.com/author/nanni"},{default:i(()=>[...e[10]||(e[10]=[t("Dan Nanni",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),o(s,{href:"https://github.com/coloka"},{default:i(()=>[...e[11]||(e[11]=[t("coloka",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),m("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创翻译，",-1)),o(s,{href:"http://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const h=l(u,[["render",d]]);export{P as __pageData,h as default};
